estimate_tranche_credit_metrics<-function(tranche_paths,target,discount_factors,confidence_level=.95,context=NULL){
 paths<-.cr_sc_checked(tranche_paths,'TrancheWaterfallPaths');.cr_data_required(target,c('event','horizon','time_unit','probability_measure','conditioning'));events<-list(TIMELY_INTEREST='timely_interest_failure',LEGAL_MATURITY_PRINCIPAL='legal_maturity_failure',ULTIMATE_PRINCIPAL='ultimate_principal_loss');if(!(target$event%in%names(events))||target$time_unit!='days'||target$probability_measure!='PHYSICAL'||target$conditioning!=paths$scenario_contract$conditioning||target$horizon!=as.numeric(.cr_data_date(tail(paths$dates,1)[[1]],'date')-.cr_data_date(paths$origin,'origin'))) .cr_error('TARGET_MISMATCH','Explicit event and actual full calendar-day physical horizon required');ctx<-.cr_result(NULL,'structured.context',context=context)$context;if(any(vapply(setdiff(names(target),'event'),function(k)!is.null(ctx[[k]])&&!identical(as.character(ctx[[k]]),as.character(target[[k]])),TRUE))||(!is.null(ctx$currency)&&ctx$currency!=paths$currency)) .cr_error('TARGET_MISMATCH','Tranche metric target conflicts with context');dates<-unlist(paths$structure_profile$payment_dates,use.names=FALSE);if(!is.list(discount_factors)||!setequal(names(discount_factors),dates)) .cr_error('STRUCTURED_DISCOUNT','One origin-based discount factor for each payment date required');for(v in discount_factors)if(.cr_sc_number(v,'discount_factor',0)==0) .cr_error('STRUCTURED_DISCOUNT','Strictly positive origin-based discount factors required');level<-.cr_sc_number(confidence_level,'confidence_level',0,1);if(level%in%c(0,1)) .cr_error('STRUCTURED_CONFIDENCE','Interior confidence level required');sids<-unlist(paths$scenario_ids,use.names=FALSE);weights<-unlist(paths$scenario_weights,use.names=FALSE);weights<-weights/.cr_sc_sum(weights);keyfn<-function(s,t).cr_hash(list(s,t));final<-setNames(paths$ending_states,vapply(paths$ending_states,function(e)keyfn(e$scenario_id,e$tranche_id),''));rows<-results<-list();iid<-paths$scenario_contract$sampling_design=='IID_UNWEIGHTED'
 for(tranche in paths$structure_profile$tranches){tid<-tranche$tranche_id;notional<-tranche$notional;selected<-numeric();ultimate<-cashloss<-list()
 for(sid in sids){e<-final[[keyfn(sid,tid)]];identified<-e$ultimate_identified;if(target$event=='ULTIMATE_PRINCIPAL'&&!identified) .cr_error('STRUCTURED_UNRESOLVED','Ultimate event requires complete pool run-off');event<-if(target$event=='ULTIMATE_PRINCIPAL')e[[events[[target$event]]]]>1e-12*max(1,notional)else e[[events[[target$event]]]];cash<-Filter(function(r)r$scenario_id==sid&&r$tranche_id==tid,paths$tranche_cashflows);expected_principal_pv<-.cr_sc_sum(notional*discount_factors[[tranche$legal_maturity]]);principal_pv<-.cr_sc_sum(vapply(cash,function(r)r$principal_paid*discount_factors[[r$date]],0.));coupon_pv<-.cr_sc_sum(vapply(cash,function(r)r$coupon_due*discount_factors[[r$date]],0.));interest_pv<-.cr_sc_sum(vapply(cash,function(r)r$interest_paid*discount_factors[[r$date]],0.));signed<-if(identified).cr_sc_sum(c(expected_principal_pv,coupon_pv,-principal_pv,-interest_pv))else NULL;shortfall<-if(identified)max(0,signed)else NULL;rows[[length(rows)+1L]]<-list(scenario_id=sid,tranche_id=tid,event=as.logical(event),ultimate_principal_loss=e$ultimate_principal_loss,contractual_principal_pv=expected_principal_pv,principal_received_pv=principal_pv,coupon_due_pv=coupon_pv,interest_received_pv=interest_pv,signed_contractual_cash_shortfall=signed,discounted_contractual_cash_shortfall=shortfall);selected<-c(selected,as.numeric(event));ultimate[length(ultimate)+1L]<-list(e$ultimate_principal_loss);cashloss[length(cashloss)+1L]<-list(shortfall)}
 pd<-.cr_sc_sum(weights*selected);positive<-which(weights>0);known<-all(vapply(ultimate[positive],function(x)!is.null(x),TRUE));expected_loss<-if(known).cr_sc_sum(vapply(positive,function(i)weights[i]*ultimate[[i]],0.))else NULL;discounted_loss<-if(known).cr_sc_sum(vapply(positive,function(i)weights[i]*cashloss[[i]],0.))else NULL;event_loss<-if(known).cr_sc_sum(vapply(positive,function(i)weights[i]*selected[i]*ultimate[[i]],0.))else NULL;interval<-mcse<-NULL
 if(iid){n<-length(sids);k<-sum(selected);alpha<-1-level;interval<-as.list(c(if(k==0)0 else stats::qbeta(alpha/2,k,n-k+1),if(k==n)1 else stats::qbeta(alpha/2,k+1,n-k,lower.tail=FALSE)));if(known&&n>1){deviations<-vapply(cashloss,function(x).cr_sc_sum(c(x,-discounted_loss))/sqrt(n*(n-1)),0.);scale<-max(abs(deviations));mcse<-if(scale==0)0 else .cr_sc_sum(scale*sqrt(.cr_sc_sum((deviations/scale)^2)))}}
 results[[length(results)+1L]]<-list(tranche_id=tid,notional=notional,event_probability=pd,event_count=as.integer(sum(selected)),positive_weight_scenarios=length(positive),event_probability_interval=interval,expected_ultimate_principal_loss=expected_loss,expected_ultimate_principal_loss_rate=if(known)expected_loss/notional else NULL,expected_discounted_contractual_cash_shortfall=discounted_loss,conditional_principal_loss_given_selected_event=if(known&&pd>0)event_loss/pd else NULL,expected_principal_loss_outside_selected_event=if(known).cr_sc_sum(c(expected_loss,-event_loss))else NULL,discounted_cash_shortfall_mcse=mcse,ultimate_identified=known)
 }
 value<-.cr_sc_bound(list(schema_version='1.0',kind='TrancheCreditMetrics',paths_hash=paths$sha256,innovation_hash=paths$innovation_hash,target=target,discount_factors=discount_factors,confidence_level=level,sampling_design=paths$scenario_contract$sampling_design,metrics=results,scenario_metrics=rows))
 .cr_result(value,'structured_credit.estimate_tranche_credit_metrics','tranche_risk',ctx,diagnostics=.cr_empty_object(),limitations='Targets distinguish timely interest, legal-maturity principal and ultimate principal; issuer default probability is never substituted. Discounted cash shortfall compares principal promised at legal maturity plus coupons actually due on opening outstanding balances against actual dated receipts; each scenario floors the combined signed shortfall at zero. This explicitly includes timing loss and is not a spread-implied fair value. Undiscounted ultimate principal loss is reported separately and is not forced to zero outside a selected payment event. Open-runoff cash shortfall and ultimate loss remain unidentified. Exact binomial intervals and sample-mean loss standard errors require caller-declared IID equally weighted scenarios; fixed weights and dependent/QMC paths receive no IID uncertainty. Conditional severity is explicitly conditional on the selected event, not a generic LGD.')
}
stress_tranche_structure<-function(baseline_paths,alternatives,target,discount_factors,confidence_level=.95,context=NULL){
 base<-.cr_sc_checked(baseline_paths,'TrancheWaterfallPaths');alternatives<-.cr_data_rows(alternatives,'alternatives');if(!length(alternatives)) .cr_error('STRUCTURED_STRESS','At least one explicit alternative required');baseline<-estimate_tranche_credit_metrics(base,target,discount_factors,confidence_level,context)$value;base_metrics<-setNames(baseline$metrics,vapply(baseline$metrics,function(m)m$tranche_id,''));comparisons<-list();seen<-character()
 for(alternative in alternatives){.cr_data_required(alternative,c('alternative_id','tranche_paths','assumption'));aid<-.cr_sc_text(alternative$alternative_id,'alternative_id');.cr_sc_text(alternative$assumption,'assumption');if(aid%in%seen) .cr_error('STRUCTURED_STRESS','Unique alternative IDs required');seen<-c(seen,aid);paths<-.cr_sc_checked(alternative$tranche_paths,'TrancheWaterfallPaths');for(key in c('scenario_ids','scenario_weights','innovation_hash','origin','currency'))if(.cr_hash(paths[[key]])!=.cr_hash(base[[key]])) .cr_error('STRUCTURED_SHARED_PATHS','Stress requires identical scenario axes, weights, origin, currency and shared innovations');metrics<-estimate_tranche_credit_metrics(paths,target,discount_factors,confidence_level,context)$value;if(!setequal(vapply(metrics$metrics,function(m)m$tranche_id,''),names(base_metrics))) .cr_error('STRUCTURED_STRESS','Comparable tranche identities required; changed notionals remain explicit');deltas<-list()
 for(m in metrics$metrics){old<-base_metrics[[m$tranche_id]];delta<-list();for(key in c('event_probability','expected_ultimate_principal_loss','expected_ultimate_principal_loss_rate','expected_discounted_contractual_cash_shortfall'))delta[key]<-list(if(!is.null(m[[key]])&&!is.null(old[[key]])) .cr_sc_sum(c(m[[key]],-old[[key]]))else NULL);deltas[[length(deltas)+1L]]<-list(tranche_id=m$tranche_id,baseline_notional=old$notional,alternative_notional=m$notional,changes=delta)}
 comparisons[[length(comparisons)+1L]]<-list(alternative_id=aid,assumption=alternative$assumption,paths_hash=paths$sha256,structure_hash=paths$structure_hash,metrics=metrics,deltas=deltas)
 }
 value<-.cr_sc_bound(list(schema_version='1.0',kind='TrancheStructureStress',baseline=baseline,baseline_structure_hash=base$structure_hash,innovation_hash=base$innovation_hash,comparisons=comparisons))
 .cr_result(value,'structured_credit.stress_tranche_structure','paired_tranche_stress',context,diagnostics=.cr_empty_object(),limitations='Alternatives are explicit evaluated economic structures or joint asset states sharing the exact innovation binding and scenario axes. Changes are paired scenario comparisons, not causal effects or an optimization guarantee. Changed notionals are reported alongside amount and rate deltas. Individual IID intervals are not intervals for paired differences; no unrequested independent-samples interval is fabricated.')
}
